const languageSelect=document.querySelector('#language-select');languageSelect.value=window.PROCUREFLOW_LANGUAGE;languageSelect.addEventListener('change',()=>{localStorage.setItem('procureflow-language',languageSelect.value);location.reload()});
const views=[...document.querySelectorAll('[data-view]')];document.querySelectorAll('[data-role]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-role]').forEach(item=>item.classList.remove('active'));button.classList.add('active');views.forEach(view=>view.hidden=view.dataset.view!==button.dataset.role);location.hash=button.dataset.role}));
const toast=(message)=>{const box=document.querySelector('#toast');box.textContent=message;box.hidden=false;setTimeout(()=>box.hidden=true,3000)};
const dialog=document.querySelector('#booking-dialog');let selectedCrop='Wheat',selectedDate='08 Sep 2026';document.querySelectorAll('[data-book]').forEach(button=>button.addEventListener('click',()=>{selectedCrop=button.dataset.crop;selectedDate=button.dataset.date;document.querySelector('#dialog-title').textContent=`${selectedCrop} procurement`;dialog.showModal()}));
document.querySelector('#confirm-booking').addEventListener('click',event=>{const form=dialog.querySelector('form');if(!form.checkValidity()){event.preventDefault();form.reportValidity();return}const token='PF-0809-01-001';localStorage.setItem('procureflow-token',JSON.stringify({token,crop:selectedCrop,date:selectedDate,status:'booked'}));setTimeout(renderToken,0);toast('Token confirmed')});
function renderToken(){const saved=JSON.parse(localStorage.getItem('procureflow-token')||'null');if(!saved)return;document.querySelector('#active-token').className='active-token';document.querySelector('#active-token').innerHTML=`<div><span class="eyebrow">Active token</span><h2>${saved.token}</h2></div><div class="token-summary"><span><small>Commodity</small>${saved.crop}</span><span><small>Date</small>${saved.date}</span><span><small>Status</small>${saved.status.replace('_',' ')}</span></div><button class="button light" data-show-staff>Track queue</button>`;document.querySelector('#active-count').textContent=saved.status==='completed'?'0':'1';document.querySelector('[data-show-staff]').addEventListener('click',()=>document.querySelector('[data-role="staff"]').click())}renderToken();
const transitions=[['booked','Booked','Check in'],['checked_in','Checked in','Start'],['serving','Serving','Complete'],['completed','Completed','Completed']];let step=0;document.querySelector('#advance-status').addEventListener('click',()=>{if(step<3)step++;const [state,label,action]=transitions[step];const status=document.querySelector('#demo-status');status.className=`large-status ${state}`;status.textContent=label;document.querySelector('#advance-status').textContent=action;if(step===3){document.querySelector('#advance-status').disabled=true;document.querySelector('#staff-completed').textContent='1';document.querySelector('#staff-waiting').textContent='0';document.querySelector('#complete-count').textContent='1'}toast(`Token status: ${label}`)});
document.querySelector('#create-demo-schedule').addEventListener('click',()=>toast('Demo schedule created'));
document.querySelector('[data-scroll-schedules]').addEventListener('click',()=>document.querySelector('#schedules').scrollIntoView({behavior:'smooth'}));
const initial=(location.hash||'#farmer').slice(1);document.querySelector(`[data-role="${initial}"]`)?.click();

